<?php
namespace App\Http\Controllers;use App\Models\AuditEvent;use Illuminate\Http\Request;
final class AuditController extends Controller {public function index(Request $r){$q=AuditEvent::where('workspace_id',session('workspace_id'))->latest('id');if($r->filled('event'))$q->where('event','like','%'.$r->input('event').'%');return view('audit.index',['events'=>$q->paginate(30)->withQueryString()]);}public function export(){return response()->streamDownload(function(){echo "[\n";$first=true;AuditEvent::where('workspace_id',session('workspace_id'))->orderBy('id')->chunk(500,function($events)use(&$first){foreach($events as $event){if(!$first)echo ",\n";$first=false;echo json_encode($event->toArray(),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);}});echo "\n]\n";},'enverif-audit-'.now()->format('Y-m-d-His').'.json',['Content-Type'=>'application/json']);}}
